import {recordActions} from './management.js';
import {E,money,icon,button,link,field,select,textarea,checkbox,table,badge,heading,notice,tabs} from './ui.js';
import {colour,colours,productImage,imageSrc,validPhone,normalizePhone,variantLabel} from './core.js';
import {modules,actions,can,fullPermissions} from './access.js';

export function attach(file,required=false,imagesOnly=false){
  if(!file||!file.size){if(required)throw Error('Upload the required document before saving.');return null;}
  const allowed=imagesOnly?['image/jpeg','image/png','image/webp']:['image/jpeg','image/png','image/webp','application/pdf'];
  if(!allowed.includes(file.type))throw Error('Use a JPG, JPEG, PNG, WebP'+(imagesOnly?'':' or PDF')+' file.');
  if(file.size>10*1024*1024)throw Error('Each file must be 10 MB or smaller.');
  return {name:file.name,type:file.type,size:file.size,url:URL.createObjectURL(file)};
}
export const fileField=(label,name,required=false,imagesOnly=false)=>field(label,name,'','file',`${required?'required ':''}accept="${imagesOnly?'image/jpeg,image/png,image/webp':'.jpg,.jpeg,.png,.webp,.pdf'}"`)+`<p class="form-help">${required?'Required. ':'Optional. '}JPG / PNG / WebP${imagesOnly?'':' / PDF'} · up to 10 MB. Available during this session.</p>`;
export const fileLink=f=>f?`<a class="text-link" href="${E(f.url)}" download="${E(f.name)}">${icon('file')}${E(f.name)}</a>`:'<span class="muted">No document</span>';
export const photo=(p,color)=>`<img class="mini-image" src="${E(productImage(p,color))}" alt="${E(p.name+' — '+colour(p,color).name)}">`;

export function colourRow(c={},index=0){return `<fieldset class="colour-editor" data-colour-row data-colour-id="${E(c.id||'')}" data-index="${index}"><legend>Colour ${index+1}</legend><div class="field-grid">${field('Colour name','colorName'+index,c.name||'','text','required placeholder="Black"')}${field('Swatch','colorHex'+index,c.hex||'#242424','color')}</div>${field('Photos for this colour','colorFiles'+index,'','file','accept="image/jpeg,image/png,image/webp" multiple')}<div class="colour-photo-preview" data-colour-previews>${(c.images||[]).map(src=>`<img src="${E(imageSrc(src))}" alt="${E(c.name||'Product colour')}">`).join('')}</div><p class="form-help">First image is the cover. New uploads replace this colour’s gallery. JPG / PNG / WebP, 10 MB per image.</p>${!c.id?button('Remove colour','remove-colour','','text-link'):''}</fieldset>`;}
export function productEditor(p){return `${field('Product name','name',p?.name||'','text','required')}${select('Category','category',['Shoes','Bags','Wallets','Socks','Belts'],p?.category||'Shoes')}<div class="field-grid">${field('Selling price','price',p?.price??'','number','required min="0" step="0.01"')}${field('Actual unit cost','cost',p?.cost??'','number','required min="0" step="0.01"')}</div>${textarea('Description — English','description',p?.description||'')}${field('Product name — বাংলা','nameBn',p?.nameBn||'')}${textarea('Description — বাংলা','descriptionBn',p?.descriptionBn||'')}${[['material','Material'],['dimensions','Fit / dimensions'],['care','Care instructions']].map(([key,label])=>`<div class="field-grid">${textarea(label+' — English',key,p?.[key]||'')}${textarea(label+' — বাংলা',key+'Bn',p?.[key+'Bn']||'')}</div>`).join('')}${field('Related product IDs (comma separated, optional)','relatedIds',p?.relatedIds?.join(', ')||'')}${field('Sizes, separated by commas','sizes',p?[...new Set(p.variants.map(v=>v.size))].join(', '):'40, 41, 42, 43','text','required')}<p class="form-help">Use “One size” for bags, belts or wallets. Existing stock variants remain in the ledger.</p><h3 class="mt">Colours & photos</h3><div id="product-colours">${(p?colours(p):[{}]).map(colourRow).join('')}</div>${button('Add another colour','add-colour','','btn secondary mt')}${select('Status','status',['Draft','Active'],p?.status||'Draft')}${notice('An active product needs a photo for every colour. New colour / size combinations start with zero stock; receive or adjust them in Inventory.')}`;}
export function readProduct(form,v,p){
  const price=Number(v.price),cost=Number(v.cost);if(!Number.isFinite(price)||price<0||!Number.isFinite(cost)||cost<0)throw Error('Enter valid non-negative prices.');
  const sizes=[...new Set(v.sizes.split(',').map(x=>x.trim()).filter(Boolean))];if(!sizes.length||sizes.some(x=>x.includes('::')))throw Error('Enter valid sizes separated by commas.');
  const rows=[...form.querySelectorAll('[data-colour-row]')],seen=new Set(),palette=[];
  if(!rows.length)throw Error('Add at least one colour.');
  for(const row of rows){const i=row.dataset.index,name=v['colorName'+i]?.trim(),hex=v['colorHex'+i];if(!name||!/^#[0-9a-f]{6}$/i.test(hex))throw Error('Add a colour name and swatch.');if(seen.has(name.toLowerCase()))throw Error('Colour names must be unique.');seen.add(name.toLowerCase());const existing=p&&colours(p).find(c=>c.id===row.dataset.colourId),files=[...(form.elements.namedItem('colorFiles'+i)?.files||[])];files.forEach(f=>{if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('Use JPG, PNG or WebP images up to 10 MB each.');});const images=files.length?files.map(f=>attach(f,true,true).url):(existing?.images||[]);if(v.status==='Active'&&!images.length)throw Error('Upload at least one photo for '+name+' before activating the product.');palette.push({id:existing?.id||'color-'+Date.now()+'-'+i,name,hex,images});}
  const variants=(p?.variants||[]).map(x=>({...x}));
  for(const c of palette)for(const size of sizes)if(!variants.some(x=>x.size===size&&x.color===c.id))variants.push({size,color:c.id,onHand:0,reserved:0});
  return {nameBn:v.nameBn||'',descriptionBn:v.descriptionBn||'',material:v.material||'',materialBn:v.materialBn||'',dimensions:v.dimensions||'',dimensionsBn:v.dimensionsBn||'',care:v.care||'',careBn:v.careBn||'',relatedIds:(v.relatedIds||'').split(',').map(x=>x.trim()).filter(Boolean),name:v.name.trim(),category:v.category,description:v.description,price,cost,status:v.status,colors:palette,color:palette[0].name,image:palette[0].images[0]||'product-placeholder.svg',variants};
}

export function inventoryView(s,tab){const rows=s.products.flatMap(p=>p.variants.filter(v=>!v.archived).map(v=>[photo(p,v.color)+`<strong>${E(p.name)}</strong>`,E(colour(p,v.color).name),E(v.size),v.onHand,v.reserved,v.onHand-v.reserved,button('View','inventory-history',`data-id="${p.id}" data-size="${E(v.size)}" data-color="${E(v.color||'')}"`,'btn small secondary')+(can(s,'inventory','edit')?button('Edit','inventory-adjust',`data-id="${p.id}" data-size="${E(v.size)}" data-color="${E(v.color||'')}"`,'btn small secondary'):'' )+(can(s,'inventory','delete')?button('Delete','variant-delete',`data-id="${p.id}" data-size="${E(v.size)}" data-color="${E(v.color||'')}"`,'btn small secondary danger'):'')]));return `${heading('Inventory','Photos, colours and stock for every variant.',can(s,'inventory','create')?button('Stock entry','new-record','data-type="stock"'):'')}${tabs([['','Stock overview'],['movements','Movement history']],tab||'','/admin/inventory/')}${s.products.some(p=>p.variants.some(v=>v.archived))?`<details class="card mb"><summary>Retired variants</summary>${s.products.map(p=>p.variants.filter(v=>v.archived).map(v=>`<p>${E(variantLabel(p,v.size,v.color))} ${button('Restore','variant-restore',`data-id="${p.id}" data-size="${E(v.size)}" data-color="${E(v.color)}"`,'text-link')}</p>`).join('')).join('')}</details>`:''}<div class="notice mb">On hand − reserved = available. Editing stock records the change and reason; earlier movements remain visible.</div>${tab==='movements'?table(['Reference','Product / variant','Type','Change','Source / document','Date',''],s.records.movements.filter(m=>!m.archived).map(m=>{const p=s.products.find(p=>p.id===m.productId||m.product?.startsWith(p.name)||m.product?.startsWith(p.id));return [E(m.id),(p?photo(p,m.color):'')+E(m.product),E(m.type),m.qty,E(m.reference)+(m.note?'<p class="small muted">'+E(m.note)+'</p>':''),E(m.date),recordActions(s,'movements',m.id)];})):table(['Product','Colour','Size','On hand','Reserved','Available',''],rows)}${tab==='movements'?notice('Source identifies the document that caused the movement: purchase receipt (PO), order (AEL), manual sale (MS), return (RMA), or stock correction (ADJ). It is not the supplier name.'):''}`;}

export function financeHistory(s){return table(['Date / reference','Action','Explanation','Changes','Document'],[...(s.financeHistory||[])].reverse().map(r=>[E(r.date)+'<p class="small muted">'+E(r.reference)+'</p>',E(r.type),E(r.explanation),r.changes.map(c=>`${E(c.account)}: ${money(c.before)} → ${money(c.after)}`).join('<br>'),fileLink(r.document)]));}
export function balanceControls(s){return `<div class="card mt"><div class="between mb"><h3>Balance corrections</h3>${can(s,'accounts','edit')?button('Edit account balance','balance-adjust','','btn secondary'):''}</div><p class="small muted">Correct an opening balance or an error with a reason. The adjustment is recorded separately from sales.</p></div><div class="mt"><h3 class="mb">Funds & transfer history</h3>${financeHistory(s)}</div>`;}
export function recordFinance(s,type,v,changes,document){s.financeHistory??=[];s.financeHistory.push({id:'FIN-'+Date.now(),date:new Date().toISOString().slice(0,10),reference:v.reference||'ADJ-'+Date.now(),type,explanation:v.explanation?.trim()||v.reason?.trim()||'',changes,document});}

export function permissionGrid(perms={}){return table(['Module','View','Create','Edit','Delete'],modules.map(([id,label])=>[E(label),...actions.map(a=>checkbox(a[0].toUpperCase()+a.slice(1),id+'__'+a,perms[id]?.includes(a)))]));}
export function readPermissions(v){return Object.fromEntries(modules.map(([id])=>{const list=actions.filter(a=>v[id+'__'+a]);if(list.some(a=>a!=='view')&&!list.includes('view'))list.unshift('view');return [id,list];}));}
export function teamEditor(s,tab){const selected=s.permissionRole||'Entry Staff',role=s.roles[selected]||{};const person=s.permissionStaff?s.records.staff.find(p=>p.id===s.permissionStaff):null;return `${heading('Team & Access','You control staff roles and individual access.',button('Add staff','new-record','data-type="staff"'))}${tabs([['','Staff'],['roles','Roles & permissions']],tab||'','/admin/team/')}${tab==='roles'?`<div class="notice mb">Your Super Admin account always has full access. Staff permissions below are configurable and do not reduce your owner access.</div><div class="toolbar">${select('Role to edit','role',Object.keys(s.roles),selected,'id="permission-role"')}${button('Create role','new-role','','btn secondary')}</div><form data-form="permissions" class="card"><h3 class="mb">${E(selected)}</h3>${permissionGrid(role)}<div class="error-text" data-error></div><button class="btn mt">Save role permissions</button></form>`:table(['Staff','Contact','Role','Status',''],s.records.staff.filter(p=>!p.archived).map(p=>[E(p.name)+'<p class="small muted">'+E(p.id)+'</p>',E(p.phone||'Phone not set')+'<p class="small muted">'+E(p.email)+'</p>',badge(p.role)+(p.customPermissions?'<p class="small">Individual permissions</p>':''),badge(p.status),recordActions(s,'staff',p.id)+(p.role!=='Super Admin'?button('Permissions','staff-permissions',`data-id="${p.id}"`,'text-link')+button('Preview access','preview-staff',`data-id="${p.id}"`,'text-link'):'')]))}<div class="card mt"><h3>Review staff access</h3>${select('Preview as','preview',['Super Admin',...Object.keys(s.roles)],s.previewRole||'Super Admin','id="preview-role"')}<p class="form-help">This is a frontend access preview. Secure permission enforcement is implemented on the server in the PHP phase.</p></div>`;}
export function staffEditor(s,p){return `${field('Full name','name',p?.name||'','text','required')}${field('Phone number','phone',p?.phone||'','tel','required autocomplete="tel" inputmode="tel"')}${field('Email','email',p?.email||'','email','required')}${field('Designation','designation',p?.designation||'')}${textarea('Address','address',p?.address||'')}${field('Joining date','joined',p?.joined||new Date().toISOString().slice(0,10),'date')}${textarea('Internal notes','notes',p?.notes||'')}${p?.role==='Super Admin'?notice('Owner account — full access is protected.') :select('Role','role',Object.keys(s.roles),p?.role||'Entry Staff')+select('Status','status',['Active','Disabled'],p?.status||'Active')}${notice('Staff data is visible in this session. No invitation or real account is created yet.')}`;}
